    { t = "Go to this week's Ritual Site: Daggerspine Point in Eversong Woods or the Broken Throne in Zul'Aman (the map marks the active one). The Curious Obelisk there sets the tier and the challenges." },
    { t = "Take the week's study from the Image of Lady Darkglen next to the Curious Obelisk (not the Lady Darkglen in Silvermoon)." },
    { t = "Each week, run a Tier 6 site with the challenges the study names: week 1 Reinforced, week 2 Malevolent Boons, week 3 Embers, week 4 Reinforced and Magical Alarm Bells, week 5 Malevolent Boons and Patrols, week 6 Embers and Manifestations." },
    { t = "Hand the study in and repeat for all six weeks." },
}
ns.ACH_NOTES[63182] = { "The six studies come as two chains of three weeks." }
ns.ACH_SPOTS[63182] = { t = "Ritual Site (only this week's site is open)", at = { { 2395, 34.9, 65.4 }, { 2437, 29.7, 78.2 } } }
ns.CRIT_NOTES[63182] = ns.CRIT_NOTES[63182] or {}
ns.CRIT_NOTES[63182]["Week 1: Reinforcements"] = { t = "Taken from the Image of Lady Darkglen at this week's Ritual Site", at = { { 2395, 34.9, 65.4 }, { 2437, 29.7, 78.2 } } }
ns.CRIT_NOTES[63182]["Week 2: Malevolent Boons"] = { t = "Taken from the Image of Lady Darkglen at this week's Ritual Site", at = { { 2395, 34.9, 65.4 }, { 2437, 29.7, 78.2 } } }
ns.CRIT_NOTES[63182]["Week 3: Embers"] = { t = "Taken from the Image of Lady Darkglen at this week's Ritual Site", at = { { 2395, 34.9, 65.4 }, { 2437, 29.7, 78.2 } } }
ns.CRIT_NOTES[63182]["Week 4: Reinforcements and Alarm Bells"] = { t = "Taken from the Image of Lady Darkglen at this week's Ritual Site", at = { { 2395, 34.9, 65.4 }, { 2437, 29.7, 78.2 } } }
ns.CRIT_NOTES[63182]["Week 5: Boons and Patrols"] = { t = "Taken from the Image of Lady Darkglen at this week's Ritual Site", at = { { 2395, 34.9, 65.4 }, { 2437, 29.7, 78.2 } } }
